// Hamburger menu
(function() {
  const btn = document.getElementById('btn-hamburger');
  const sidebar = document.getElementById('main-sidebar');
  const overlay = document.getElementById('sidebar-overlay');
  if (btn && sidebar && overlay) {
    const main = document.querySelector('main');
    const mobile = window.matchMedia('(max-width: 768px)');
    function setOpen(open, restore) {
      sidebar.classList.toggle('open', open);
      overlay.classList.toggle('active', open);
      btn.setAttribute('aria-expanded', String(open));
      btn.setAttribute('aria-label', open ? 'Cerrar menú' : 'Abrir menú');
      sidebar.inert = mobile.matches && !open;
      main.inert = mobile.matches && open;
      if (open) sidebar.querySelector('a').focus();
      else if (restore) btn.focus();
    }
    setOpen(false, false);
    btn.addEventListener('click', () => {
      setOpen(!sidebar.classList.contains('open'), true);
    });
    overlay.addEventListener('click', () => setOpen(false, true));
    mobile.addEventListener('change', () => setOpen(false, false));
    document.addEventListener('keydown', (event) => {
      if (!mobile.matches || !sidebar.classList.contains('open')) return;
      if (event.key === 'Escape') { event.preventDefault(); setOpen(false, true); }
      if (event.key === 'Tab') {
        const items = Array.from(sidebar.querySelectorAll('a,button')).filter(el => !el.disabled);
        const first = items[0], last = items[items.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); btn.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); btn.focus(); }
        else if (document.activeElement === btn) { event.preventDefault(); (event.shiftKey ? last : first).focus(); }
      }
    });
  }
})();

// Hamburger menu
var btn = document.getElementById('btn-hamburger');
var sidebar = document.getElementById('main-sidebar');
var overlay = document.getElementById('sidebar-overlay');
if (btn && sidebar && overlay) {
  function closeMenu() {
    sidebar.classList.remove('open');
    overlay.classList.remove('active');
    btn.setAttribute('aria-expanded', 'false');
    btn.focus();
  }
  btn.addEventListener('click', function() {
    var open = !sidebar.classList.contains('open');
    sidebar.classList.toggle('open', open);
    overlay.classList.toggle('active', open);
    btn.setAttribute('aria-expanded', String(open));
    if (open) sidebar.querySelector('a').focus();
  });
  overlay.addEventListener('click', closeMenu);
  document.addEventListener('keydown', function(event) {
    if (event.key === 'Escape' && sidebar.classList.contains('open')) closeMenu();
  });
}

