function clearSharePreparation() {
  _shareFile = null;
  _sharePlan = null;
  _shareSession = null;
  const button = document.getElementById('s3-whatsapp');
  if (button) button.textContent = '📲 Preparar para WhatsApp';
}

document.getElementById('s3-whatsapp').addEventListener('click', async () => {
  if (!_cliente_sel || !_plan_result || _generationSessionDiscarded) return;
  const button = document.getElementById('s3-whatsapp');
  const status = document.getElementById('s3-download-status');
  const epoch = _generationEpoch;
  const plan = _plan_result;
  button.disabled = true;
  try {
    if (!_shareFile || _sharePlan !== plan) {
      clearSharePreparation();
      await verifyGenerationAccount(epoch);
      if (plan !== _plan_result) throw new Error('El plan cambió. Vuelve a prepararlo.');
      if (typeof navigator.share !== 'function' || typeof navigator.canShare !== 'function' || typeof File !== 'function') {
        status.textContent = 'Para enviarlo por WhatsApp, descarga el PDF y adjúntalo en la conversación con tu cliente.';
        return;
      }
      const blob = await Api.planes.obtenerPdfPorPlan(plan.plan_id);
      await verifyGenerationAccount(epoch);
      if (plan !== _plan_result) throw new Error('El plan cambió. Vuelve a prepararlo.');
      const file = new File([blob], 'plan-alimenticio.pdf', {type: 'application/pdf'});
      if (!navigator.canShare({files: [file]})) {
        status.textContent = 'Este dispositivo no puede compartir el archivo directamente. Descarga el PDF y adjúntalo en WhatsApp.';
        return;
      }
      _shareFile = file;
      _sharePlan = plan;
      _shareSession = Api.session.capture();
      button.textContent = '📲 Compartir PDF';
      status.textContent = 'PDF preparado. Pulsa Compartir PDF y elige WhatsApp y el destinatario.';
      return;
    }
    const file = _shareFile;
    if (_sharePlan !== _plan_result || epoch !== _generationEpoch) throw new Error('El plan cambió. Vuelve a prepararlo.');
    Api.session.check(_shareSession);
    await navigator.share({files: [file], title: 'Plan alimenticio'});
    clearSharePreparation();
    if (epoch !== _generationEpoch || _generationSessionDiscarded) return;
    status.textContent = 'Se abrió el selector para compartir. Comprueba el envío en WhatsApp.';
  } catch (error) {
    clearSharePreparation();
    if (epoch !== _generationEpoch || _generationSessionDiscarded) return;
    status.textContent = error && error.name === 'AbortError'
      ? 'Se canceló la selección. Puedes volver a preparar el PDF.'
      : 'No se pudo compartir el PDF. Descárgalo y adjúntalo en WhatsApp.';
  } finally { button.disabled = false; }

