document.getElementById('registroForm').addEventListener('submit', async function(e) {
  e.preventDefault();
  var form = e.target;
  var errorMsg   = document.getElementById('errorMsg');
  var successMsg = document.getElementById('successMsg');
  var btn = document.getElementById('submitBtn');

  errorMsg.style.display   = 'none';
  successMsg.style.display = 'none';

  var pw1 = form.password.value;
  var pw2 = form.confirm_password.value;

  if (pw1 !== pw2) {
    errorMsg.textContent = 'Las contraseñas no coinciden.';
    errorMsg.style.display = 'block';
    return;
  }
  if (Array.from(pw1).length < 15 || new TextEncoder().encode(pw1).length > 72) {
    errorMsg.textContent = 'La contraseña debe tener al menos 15 caracteres y como máximo 72 bytes UTF-8.';
    errorMsg.style.display = 'block';
    return;
  }

  btn.disabled = true;
  btn.textContent = 'Creando cuenta...';

  try {
    await Api.session.ready;
    var data = await Api.auth.registro({
        email: form.email.value.trim(),
        password: pw1,
        nombre: form.nombre.value.trim(),
        apellido: form.apellido.value.trim(),
        tipo: form.tipo.value,
    });
      var context=Api.session.accepted(data);
      form.password.value='';form.confirm_password.value='';
      successMsg.textContent = '¡Cuenta creada! Redirigiendo...';
      successMsg.style.display = 'block';
      var dest = data.tipo === 'gym' ? '/configuracion' : '/mi-plan';
      Api.session.check(context);window.location.replace(dest);
  } catch (err) {
    errorMsg.textContent = err.code==='browser_session_unconfirmed'?'No pudimos confirmar la creación. Puede haberse aplicado; inicia sesión o recupera el acceso antes de repetirla.':err.message||'No se pudo confirmar la creación de la cuenta.';
    errorMsg.style.display = 'block';
  } finally {
    btn.disabled = false;
    btn.textContent = 'Crear Cuenta →';
  }
});
window.addEventListener('metodobase-session-changed',function(){var form=document.getElementById('registroForm');form.password.value='';form.confirm_password.value='';});
window.addEventListener('pagehide',function(){var form=document.getElementById('registroForm');form.reset();});

