async function abrirPDF(planId, button) {
  if (!personal.validPlanId(planId) || button.disabled) return;
  var popup = window.open('about:blank', '_blank');
  if (!popup) { showToast('Permite las ventanas emergentes para abrir el PDF.', 'error'); return; }
  try { popup.opener = null; } catch { popup.close(); showToast('No se pudo abrir el PDF.', 'error'); return; }
  button.disabled = true;
  try {
    await personal.read(function(context) { return Api.usuario.abrirPlan(planId, context, popup); });
    personal.check();
  } catch(e) {
    popup.close();
    if (personal.active) showToast(e.message || 'No se pudo abrir el PDF.', 'error');
  } finally { if (personal.active) button.disabled = false; }

